"""Small-output BF16 mHC projection, with no activation normalization.

The fixed GLM shape is [..., 16384] @ [24, 16384].T with one or two
activation rows. Inputs are read-only. A 32-way split-K writes FP32 partials;
a second kernel reduces them deterministically and rounds once to BF16.
Reduction order differs from BLAS, so bitwise BLAS equivalence is not promised.

Torch and Triton are optional and loaded only on invocation. Call once eagerly
for each device/row-count before graph capture: this compiles and autotunes six
launch configurations. The warmed path allocates graph-pool-compatible scratch.
Tuning is in-process, keyed by device ordinal and row count, not a portable
deployment artifact. Retune in a fresh process after changing hardware/software.
"""

from functools import lru_cache

_WARMED = set()


def _validate(x, weight, *, gpu):
    import torch

    if x.ndim < 1 or x.shape[-1] != 16384 or tuple(weight.shape) != (24, 16384):
        raise ValueError("expected x [...,16384] and weight [24,16384]")
    rows = x.numel() // 16384
    if rows not in (1, 2):
        raise ValueError("mHC projection supports one or two activation rows")
    if x.dtype != torch.bfloat16 or weight.dtype != torch.bfloat16:
        raise TypeError("mHC projection requires BF16 inputs")
    if x.device != weight.device or (gpu and not x.is_cuda):
        raise ValueError("inputs must share a GPU device" if gpu else "inputs must share a device")
    if not x.is_contiguous() or not weight.is_contiguous():
        raise ValueError("mHC projection requires contiguous inputs")
    return rows


def mhc_projection_reference(normalized_x, weight):
    """FP32-accumulating Torch reference, available on CPU and GPU."""
    import torch

    _validate(normalized_x, weight, gpu=False)
    return torch.nn.functional.linear(normalized_x.float(), weight.float()).to(torch.bfloat16)


@lru_cache(maxsize=1)
def _kernels():
    # Put tl in the module namespace for Triton's annotation/source resolution.
    global tl
    import triton
    import triton.language as tl

    @triton.autotune(
        configs=[triton.Config({"ROWS": rows}, num_warps=warps)
                 for rows in (1, 2, 4) for warps in (4, 8)],
        key=["TOKENS", "DEVICE"],
    )
    @triton.jit
    def partial(X, W, P, TOKENS: tl.constexpr, DEVICE: tl.constexpr, ROWS: tl.constexpr):
        token = tl.program_id(2)
        split = tl.program_id(1)
        row = tl.program_id(0) * ROWS + tl.arange(0, ROWS)
        col = split * 512 + tl.arange(0, 512)
        x = tl.load(X + token * 16384 + col).to(tl.float32)
        w = tl.load(W + row[:, None] * 16384 + col[None, :], row[:, None] < 24, 0).to(tl.float32)
        value = tl.sum(w * x[None, :], axis=1)
        tl.store(P + (token * 24 + row) * 32 + split, value, row < 24)

    @triton.jit
    def reduce(P, Y, TOKENS: tl.constexpr):
        row = tl.program_id(0) * 4 + tl.arange(0, 4)
        split = tl.arange(0, 32)
        value = tl.load(P + row[:, None] * 32 + split[None, :], row[:, None] < TOKENS * 24, 0)
        out = tl.sum(value, axis=1)
        tl.store(Y + row, out, row < TOKENS * 24)

    return partial, reduce


def mhc_projection(normalized_x, weight):
    """Return BF16 linear output; eager warmup is required before GPU capture.

    This is an inference-only operator without an autograd backward. It does
    not normalize activations or fuse the subsequent mHC gate/Sinkhorn math.
    """
    import torch

    tokens = _validate(normalized_x, weight, gpu=True)
    with torch.cuda.device(normalized_x.device):
        device = normalized_x.device.index
        key = (device, tokens)
        if torch.cuda.is_current_stream_capturing() and key not in _WARMED:
            raise RuntimeError("warm up mhc_projection eagerly on this device/row-count before capture")
        partial, reduce = _kernels()
        scratch = torch.empty((tokens, 24, 32), dtype=torch.float32, device=normalized_x.device)
        out = torch.empty((*normalized_x.shape[:-1], 24), dtype=torch.bfloat16, device=normalized_x.device)
        partial[lambda meta: ((24 + meta["ROWS"] - 1) // meta["ROWS"], 32, tokens)](
            normalized_x, weight, scratch, tokens, device, enable_fp_fusion=False,
        )
        reduce[(tokens * 6,)](scratch, out, tokens, num_warps=4, enable_fp_fusion=False)
        _WARMED.add(key)
    return out


def mhc_projection_tuning_metadata():
    """Return JSON-safe in-process tuning choices for benchmark reports."""
    if not _kernels.cache_info().currsize:
        return {"split_k": 32, "choices": []}
    partial, _ = _kernels()
    return {
        "split_k": 32,
        "choices": [
            {"key": repr(key), "kwargs": dict(config.kwargs), "num_warps": config.num_warps}
            for key, config in partial.cache.items()
        ],
    }

"""Decode-only BF16 Q/K/V projection without packing or copying weights.

Each weight is [8192,4096]; x has one or two rows. One launch computes all
three projections with FP32 tree reductions and rounds the concatenated
Q/K/V result once to BF16. Reduction order can differ from BLAS.

Torch and Triton load lazily. Warm up each device/row-count eagerly before
graph capture. Eight configurations are autotuned in process, not persisted;
retune in a fresh process after hardware or software changes. Inputs are
read-only, and this inference-only operator has no autograd backward.
"""

from functools import lru_cache

_WARMED = set()


def _validate(x, weights, *, gpu):
    import torch

    if x.ndim < 1 or x.shape[-1] != 4096 or any(tuple(w.shape) != (8192, 4096) for w in weights):
        raise ValueError("expected x [...,4096] and three weights [8192,4096]")
    tokens = x.numel() // 4096
    if tokens not in (1, 2):
        raise ValueError("QKV projection supports one or two activation rows")
    if x.dtype != torch.bfloat16 or any(w.dtype != torch.bfloat16 for w in weights):
        raise TypeError("QKV projection requires BF16 inputs")
    if any(w.device != x.device for w in weights) or (gpu and not x.is_cuda):
        raise ValueError("inputs must share a GPU device" if gpu else "inputs must share a device")
    if not x.is_contiguous() or any(not w.is_contiguous() for w in weights):
        raise ValueError("QKV projection requires contiguous inputs")
    return tokens


def qkv_projection_reference(x, q_weight, k_weight, v_weight):
    """FP32-accumulating Torch reference, available on CPU and GPU."""
    import torch

    weights = (q_weight, k_weight, v_weight)
    _validate(x, weights, gpu=False)
    return torch.cat([
        torch.nn.functional.linear(x.float(), weight.float()).to(torch.bfloat16)
        for weight in weights
    ], dim=-1)


@lru_cache(maxsize=1)
def _kernel():
    global tl
    import triton
    import triton.language as tl

    @triton.autotune(
        configs=[triton.Config({"ROWS": rows}, num_warps=warps)
                 for rows in (1, 2, 4, 8) for warps in (4, 8)],
        key=["TOKENS", "DEVICE"],
    )
    @triton.jit
    def project(X, Q, K, V, Y, TOKENS: tl.constexpr, DEVICE: tl.constexpr, ROWS: tl.constexpr):
        projection = tl.program_id(1)
        token = tl.program_id(2)
        row = tl.program_id(0) * ROWS + tl.arange(0, ROWS)
        col = tl.arange(0, 4096)
        # A whole program reads exactly one original matrix. No packed weight
        # allocation, activation normalization, or intermediate tensor is used.
        if projection == 0:
            weight = Q
        elif projection == 1:
            weight = K
        else:
            weight = V
        x = tl.load(X + token * 4096 + col).to(tl.float32)
        w = tl.load(weight + row[:, None] * 4096 + col[None, :], row[:, None] < 8192, 0).to(tl.float32)
        value = tl.sum(w * x[None, :], axis=1)
        tl.store(Y + token * 24576 + projection * 8192 + row, value, row < 8192)

    return project


def qkv_projection(x, q_weight, k_weight, v_weight):
    """Return contiguous BF16 [...,24576], ordered Q then K then V."""
    import torch

    tokens = _validate(x, (q_weight, k_weight, v_weight), gpu=True)
    with torch.cuda.device(x.device):
        device = x.device.index
        key = (device, tokens)
        if torch.cuda.is_current_stream_capturing() and key not in _WARMED:
            raise RuntimeError("warm up qkv_projection eagerly on this device/row-count before capture")
        project = _kernel()
        out = torch.empty((*x.shape[:-1], 24576), dtype=torch.bfloat16, device=x.device)
        project[lambda meta: ((8192 + meta["ROWS"] - 1) // meta["ROWS"], 3, tokens)](
            x, q_weight, k_weight, v_weight, out, tokens, device, enable_fp_fusion=False,
        )
        _WARMED.add(key)
    return out


def qkv_projection_tuning_metadata():
    """Return JSON-safe in-process tuning choices for benchmark reports."""
    if not _kernel.cache_info().currsize:
        return {"choices": []}
    return {"choices": [
        {"key": repr(key), "kwargs": dict(config.kwargs), "num_warps": config.num_warps}
        for key, config in _kernel().cache.items()
    ]}

"""Opt-in, pre-tuned BLAS QKV for serialized inference only.

Configuration reads a PyTorch-version-validated TunableOp artifact eagerly.
Calls never tune or read files. TunableOp flags and its result table are
process-global: callers must serialize configuration/inference against all
other BLAS work in this process. Flag restoration does not isolate concurrent
threads, remove loaded results, or undo an already captured graph's choices.
Torch remains optional until an API is invoked.
"""

import csv
from contextlib import contextmanager

from .qkv_projection import _validate

_OP = "GemmTunableOp_BFloat16_TN"
_CONFIGURED = {}


def _signature(tokens):
    return f"tn_8192_{tokens}_4096_ld_4096_4096_8192"


@contextmanager
def _enabled_without_tuning(tunable):
    enabled, tuning = tunable.is_enabled(), tunable.tuning_is_enabled()
    try:
        tunable.tuning_enable(False)
        tunable.enable(True)
        if not tunable.is_enabled() or tunable.tuning_is_enabled():
            raise RuntimeError("TunableOp environment overrides prevent frozen QKV execution")
        yield
    finally:
        try:
            tunable.enable(enabled)
        finally:
            tunable.tuning_enable(tuning)


def configure_qkv_tuned_blas(path):
    """Load an artifact before capture; reject missing/default QKV winners.

    PyTorch read_file performs hardware/library validator checks. Results are
    then checked against this exact file so a preexisting global result cannot
    silently stand in for the requested winner. Returns configured row counts.
    A failed configuration leaves this wrapper disabled (global results may
    still contain entries loaded by PyTorch).
    """
    import torch
    import torch.cuda.tunable as tunable

    global _CONFIGURED
    _CONFIGURED = {}
    if torch.cuda.is_current_stream_capturing():
        raise RuntimeError("configure qkv_tuned_blas eagerly before capture")
    with open(path, newline="") as source:
        rows = list(csv.reader(source))
    validators = {row[1] for row in rows if len(row) >= 3 and row[0] == "Validator"}
    required = {"PT_VERSION", "ROCM_VERSION", "HIPBLASLT_VERSION", "GCN_ARCH_NAME", "ROCBLAS_VERSION"}
    if not required.issubset(validators):
        raise ValueError("QKV tuning artifact must include PyTorch/ROCm/library/device validators")
    expected = {
        tokens: row[2]
        for tokens in (1, 2) for row in rows
        if len(row) >= 3 and row[0] == _OP and row[1] == _signature(tokens)
        and row[2] and row[2] != "Default"
    }
    if 1 not in expected:
        raise ValueError("QKV tuning artifact requires a non-Default one-token shape entry")
    with _enabled_without_tuning(tunable):
        if not tunable.read_file(str(path)):
            raise RuntimeError("PyTorch rejected QKV tuning artifact validators")
        loaded = {(row[0], row[1]): row[2] for row in tunable.get_results()}
        if any(loaded.get((_OP, _signature(tokens))) != winner for tokens, winner in expected.items()):
            raise RuntimeError("loaded QKV tuning results do not match the requested artifact")
    _CONFIGURED = expected
    return tuple(sorted(expected))


def qkv_tuned_blas(x, q_weight, k_weight, v_weight):
    """Compute BF16 Q/K/V with preloaded winners, restoring global flags."""
    import torch
    import torch.cuda.tunable as tunable

    weights = (q_weight, k_weight, v_weight)
    tokens = _validate(x, weights, gpu=True)
    if tokens not in _CONFIGURED:
        raise RuntimeError("configure qkv_tuned_blas eagerly for this row count before use")
    with torch.cuda.device(x.device), _enabled_without_tuning(tunable):
        return torch.cat([torch.nn.functional.linear(x, weight) for weight in weights], dim=-1)

